const page0 = figma.root.children.find(p => p.id === '0:1' || p.name.includes('00'));
await figma.setCurrentPageAsync(page0);

function dumpNode(node, depth = 0) {
  let indent = '  '.repeat(depth);
  let res = `${indent}- [${node.type}] "${node.name}" (id: ${node.id})\n`;
  if (node.type === 'TEXT') {
    res += `${indent}  TEXT: "${node.characters.replace(/\n/g, '\\n')}"\n`;
  }
  if ('children' in node) {
    for (const child of node.children) {
      res += dumpNode(child, depth + 1);
    }
  }
  return res;
}

return dumpNode(page0);

const pFoundations = figma.root.children.find(p => p.id === '1:2' || p.name.includes('Foundations'));
const pComponents = figma.root.children.find(p => p.id === '1:3' || p.name.includes('Components'));
const pMedia = figma.root.children.find(p => p.id === '1:4' || p.name.includes('Media'));

function dumpTopLevel(page) {
  if (!page) return 'Page not found';
  let res = `Page "${page.name}" top level:\n`;
  for (const child of page.children) {
    res += `- [${child.type}] "${child.name}" (id: ${child.id})\n`;
  }
  return res;
}

return {
  foundations: dumpTopLevel(pFoundations),
  components: dumpTopLevel(pComponents),
  media: dumpTopLevel(pMedia)
};

const fFoundations = figma.getNodeById('1:5');
const fComponents = figma.getNodeById('1:20');
const fMedia = figma.getNodeById('1:222');

function dumpChildren(node) {
  if (!node) return 'None';
  let res = `Node "${node.name}" children:\n`;
  for (const child of node.children) {
    res += `  - [${child.type}] "${child.name}" (id: ${child.id})\n`;
  }
  return res;
}

return {
  foundations: dumpChildren(fFoundations),
  components: dumpChildren(fComponents),
  media: dumpChildren(fMedia)
};

