const cHomeIndicator = figma.getNodeById('1:42');

function getCompDetails(node) {
  if (!node) return 'None';
  return {
    name: node.name,
    type: node.type,
    id: node.id,
    width: node.width,
    height: node.height,
    children: node.children ? node.children.map(c => `${c.type} "${c.name}"`).join(', ') : 'None'
  };
}

return {
  Button: getCompDetails(cButton),
  TextField: getCompDetails(cTextField),
  StatusBar: getCompDetails(cStatusBar),
  HomeIndicator: getCompDetails(cHomeIndicator)
};

const brandColors = figma.getNodeById('1:9');
if (!brandColors) return 'Not found';

function dumpAllNodes(node, depth = 0) {
  let indent = '  '.repeat(depth);
  let res = `${indent}- [${node.type}] "${node.name}" (id: ${node.id})\n`;
  if (node.fills && node.fills.length > 0) {
    res += `${indent}  Fills: ${JSON.stringify(node.fills)}\n`;
  }
  if ('children' in node) {
    for (const child of node.children) {
      res += dumpAllNodes(child, depth + 1);
    }
  }
  return res;
}

return dumpAllNodes(brandColors);

const pageWorkspace = figma.root.children.find(p => p.id === '3:2' || p.name.includes('03'));
await figma.setCurrentPageAsync(pageWorkspace);

// Clear workspace page first to ensure fresh build
for (const child of pageWorkspace.children) {
  child.remove();
}

// Load fonts
await Promise.all([
  figma.loadFontAsync({ family: "Inter", style: "Regular" }),
  figma.loadFontAsync({ family: "Inter", style: "Medium" }),
  figma.loadFontAsync({ family: "Inter", style: "Semi Bold" })
]);

const frameNames = [
  "01_Welcome", "02_Email_Sign_In", "03_Create_Member", "04_Personalize_Intro",
  "05_Products_You_Use", "06_Shoe_Size", "07_Interests", "08_Notifications",
  "09_Welcome_To_App", "10_Home", "11_Discover", "12_Shop",
  "13_Best_Sellers", "14_Jordan_Flight_Essentials", "15_Product_Detail", "16_Style_Matching",
  "17_Stores", "18_Playlist_Story"
];

const darkFrames = ["04_Personalize_Intro", "05_Products_You_Use", "06_Shoe_Size", "07_Interests", "08_Notifications"];

const createdFrames = {};

const statusBarComp = figma.getNodeById('1:32');
const homeIndicatorComp = figma.getNodeById('1:42');

for (let i = 0; i < frameNames.length; i++) {
  const name = frameNames[i];
  const col = i % 6;
  const row = Math.floor(i / 6);

  const frame = figma.createFrame();
  frame.name = name;
  frame.resize(375, 812);
  frame.x = col * (375 + 100);
  frame.y = row * (812 + 200);

  // Set background color
  const isDark = darkFrames.includes(name);
  frame.fills = [{
    type: "SOLID",
    color: isDark ? { r: 0.067, g: 0.067, b: 0.067 } : { r: 1, g: 1, b: 1 }
  }];

  // Add Status Bar
  const sb = statusBarComp.createInstance();
  sb.name = "Status Bar";
  sb.x = 0;
  sb.y = 0;
  frame.appendChild(sb);

  // If dark mode, invert status bar elements
  if (isDark) {
    // Invert text and icons inside status bar to white
    function makeWhite(node) {
      if (node.type === 'TEXT') {
        node.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
      } else if (node.type === 'VECTOR' || node.type === 'BOOLEAN_OPERATION' || node.type === 'RECTANGLE' || node.type === 'ELLIPSE') {
        node.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
      }
      if ('children' in node) {
        for (const child of node.children) {
          makeWhite(child);
        }
      }
    }
    makeWhite(sb);
  }

  // Add Home Indicator
  const hi = homeIndicatorComp.createInstance();
  hi.name = "Home Indicator";
  hi.x = 0;
  hi.y = 778;
  frame.appendChild(hi);

  if (isDark) {
    const rect = hi.findOne(c => c.name === "Rectangle");
    if (rect) {
      rect.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    }
  }

  pageWorkspace.appendChild(frame);
  createdFrames[name] = frame.id;
}

return createdFrames;

