// Helper to create a fully customized Text Field by detaching
function createCustomTextField(labelText, valueText = "", iconNode = null, width = 335) {
  const inst = findNode("1:27").createInstance();
  inst.resize(width, 56);
  const frame = inst.detachInstance();
  frame.name = labelText + " Field";

  const lbl = frame.findOne(c => c.type === 'TEXT');
  if (lbl) {
    lbl.characters = labelText;
    lbl.fontSize = 12;
    lbl.y = 8;
  }

  if (valueText) {
    const valText = figma.createText();
    valText.fontName = { family: "Inter", style: "Regular" };
    valText.fontSize = 15;
    valText.characters = valueText;
    valText.fills = [{ type: "SOLID", color: { r: 0.1, g: 0.1, b: 0.1 } }];
    valText.x = 16;
    valText.y = 26;
    frame.appendChild(valText);
  }

  if (iconNode) {
    const iconClone = iconNode.clone();
    iconClone.x = width - 36;
    iconClone.y = 16;
    frame.appendChild(iconClone);
  }
  return frame;
}

// Clear any kids on fWelcome, fSignIn, fCreateMember except Status Bar & Home Indicator
function clearContents(frame) {
  for (const child of frame.children) {
    if (child.name !== "Status Bar" && child.name !== "Home Indicator") {
      child.remove();
    }
  }
}

