// Helper to create progress bar
function createProgressBar(step, totalSteps = 5) {
  const bar = figma.createFrame();
  bar.name = `Progress Bar Step ${step}`;
  bar.resize(335, 4);
  bar.x = 20;
  bar.y = 56;
  bar.fills = [{ type: "SOLID", color: { r: 0.2, g: 0.2, b: 0.2 } }];
  bar.cornerRadius = 2;

  const fill = figma.createRectangle();
  fill.name = "Fill";
  fill.resize((335 / totalSteps) * step, 4);
  fill.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
  fill.cornerRadius = 2;
  bar.appendChild(fill);
  return bar;
}

// Helper to build a standard white Tab Bar (light mode)
function addTabBar(frame, activeTab = "") {
  const container = figma.createFrame();
  container.name = "Navigation Tab Bar";
  container.resize(375, 83);
  container.x = 0;
  container.y = 729; // Sits nicely above Home Indicator
  container.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
  container.strokes = [{ type: "SOLID", color: { r: 0.9, g: 0.9, b: 0.9 } }];
  container.strokeAlign = "INSIDE";
  container.strokeWeight = 0.5;

  const tabs = [
    { name: "Home", iconId: "1:357" },
    { name: "Shop", iconId: "1:367" },
    { name: "Favorites", iconId: "1:353" },
    { name: "Bag", iconId: "1:343" },
    { name: "Profile", iconId: "1:361" }
  ];

  const tabW = 375 / tabs.length;
  for (let i = 0; i < tabs.length; i++) {
    const tab = tabs[i];
    const isCurrent = (tab.name.toLowerCase() === activeTab.toLowerCase());

    const tabFrame = figma.createFrame();
    tabFrame.name = `Tab_${tab.name}`;
    tabFrame.resize(tabW, 49);
    tabFrame.x = i * tabW;
    tabFrame.y = 0;
    tabFrame.fills = [];

    // Icon
    const icon = findNode(tab.iconId).clone();
    icon.x = (tabW - 24) / 2;
    icon.y = 6;

    // Set icon opacity/color based on active state
    function recolorIcon(n) {
      if (n.fills) {
        n.fills = [{ type: 'SOLID', color: { r: 0.067, g: 0.067, b: 0.067 } }];
        n.opacity = isCurrent ? 1 : 0.4;
      }
      if ('children' in n) n.children.forEach(recolorIcon);
    }
    recolorIcon(icon);
    tabFrame.appendChild(icon);

    // Label
    const lbl = figma.createText();
    lbl.fontName = { family: "Inter", style: isCurrent ? "Semi Bold" : "Medium" };
    lbl.fontSize = 10;
    lbl.characters = tab.name;
    lbl.fills = [{ type: "SOLID", color: { r: 0.067, g: 0.067, b: 0.067 } }];
    lbl.opacity = isCurrent ? 1 : 0.4;
    lbl.textAlignHorizontal = "CENTER";
    lbl.resize(tabW, 12);
    lbl.x = 0;
    lbl.y = 32;
    tabFrame.appendChild(lbl);

    container.appendChild(tabFrame);
  }

  frame.appendChild(container);

  // Make sure Home Indicator is on top of Tab Bar
  const hi = frame.findOne(c => c.name === "Home Indicator");
  if (hi) {
    frame.appendChild(hi);
  }
}

