  const isUnavailable = (status.toLowerCase() === "unavailable");

  // Image container
  const imgBg = figma.createFrame();
  imgBg.name = "Image Background";
  imgBg.resize(width, 150);
  imgBg.x = 0;
  imgBg.y = 0;
  imgBg.fills = [{ type: "SOLID", color: { r: 0.96, g: 0.96, b: 0.96 } }];
