function setLink(source, targetNode) {
  if (!source) return;
  source.reactions = [{
    action: {
      type: "NODE",
      destinationId: targetNode.id,
      navigation: "NAVIGATE",
      transition: null
    },
    trigger: { type: "ON_CLICK" }
  }];
}

// Helper to wire a specific tab in a Tab Bar
function wireTab(parentFrame, tabName, targetFrame) {
  const tabBar = parentFrame.findOne(c => c.name === "Navigation Tab Bar");
  if (tabBar) {
    const tabNode = tabBar.findOne(c => c.name === `Tab_${tabName}`);
    if (tabNode) {
      setLink(tabNode, targetFrame);
    }
  }
}

